import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new __InvMutHandleStub())); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        // keep the fuzzed ancillary data small so the comparison baseline is stable
        vm.assume(ancillaryData.length < 32);

        // the only authorized caller is the deployed OptimisticAsserter (the stub)
        address asserter = address(c.optimisticAsserter());

        // drive c through requestPrice from the asserter and measure gas actually consumed by c
        uint256 beforePrice = gasleft();
        vm.prank(asserter);
        c.requestPrice(identifier, time, ancillaryData);
        uint256 gasPrice = beforePrice - gasleft();

        // baseline: an identical access-controlled entry on c whose correct body is EMPTY
        // (assertionDisputedCallback takes only a bytes32; extra calldata cost is paid by
        //  the caller identically in both calls and cancels out)
        uint256 beforeEmpty = gasleft();
        vm.prank(asserter);
        c.assertionDisputedCallback(identifier);
        uint256 gasEmpty = beforeEmpty - gasleft();

        // General rule: an authorized requestPrice must do observable work (emit the
        // PriceRequestAdded event), consuming clearly more gas than c's empty guarded call.
        // The mutant's requestPrice is empty, so gasPrice ~ gasEmpty and this fails.
        assertTrue(gasPrice > gasEmpty + 500, "requestPrice must emit PriceRequestAdded");
    }
}

