contract InvMutTest is Test {
    C c;
    address asserter;

    function setUp() public {
        asserter = address(new __InvMutHandleStub());
        c = new C(asserter);
    }

    function testFuzz_property(bytes32 assertionId) public {
        // The only authorized caller is the optimisticAsserter; warm up both the
        // account access and the code path with one call, then measure the second.
        vm.prank(asserter);
        c.assertionDisputedCallback(assertionId);

        vm.prank(asserter);
        uint256 g0 = gasleft();
        c.assertionDisputedCallback(assertionId);
        uint256 used = g0 - gasleft();

        // General rule: for EVERY assertionId, an authorized invocation of
        // assertionDisputedCallback performs no bookkeeping and emits no log,
        // so it must consume less than 1000 gas of a warmed call.
        // The mutant emits PriceRequestAdded on every invocation, exceeding
        // this bound for every (hence some) fuzzed assertionId.
        assertTrue(used < 1000, "assertionDisputedCallback must be a no-op");
    }
}
